"""Snap span edges to a fixed step for payroll."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span

def check_step(step: int) -> None:
    """Raise ValueError unless step divides an hour."""
    if step <= 0 or 60 % step != 0:
        raise ValueError(
            f"step must divide an hour evenly: {step!r}"
        )

def round_half_up(value: int, step: int) -> int:
    lower = value // step * step
    if (value - lower) * 2 >= step:
        return lower + step
    return lower

def format_duration(minutes: int) -> str:
    hours, remainder = divmod(minutes, 60)
    return f"{hours}h {remainder}m"

# ---
def round_spans(
    spans: Iterable[Span], step: int
) -> List[Span]:
    """Round each start and end to the nearest step.

    Raises ValueError for a bad step, or when a span is so
    short that both edges land on the same step.
    """
    check_step(step)
    return [
        Span(
            round_half_up(span.start, step),
            round_half_up(span.end, step),
        )
        for span in spans
    ]

# ---
def rounded_labels(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Labels such as 09:00-17:15 (8h 15m), one per span."""
    return [
        f"{format_span(span)} "
        f"({format_duration(span.minutes)})"
        for span in round_spans(spans, step)
    ]

