# owner: platform
import unittest

from hourglass.rounding import round_spans, rounded_labels
from hourglass.models import Span

class RoundSpansTests(unittest.TestCase):
    def test_nearest_step_down_and_up(self):
        self.assertEqual(
            round_spans([Span(547, 1027)], 15),
            [Span(540, 1020)],
        )

    def test_halfway_goes_up(self):
        self.assertEqual(
            round_spans([Span(53, 127)], 15),
            [Span(60, 120)],
        )

    def test_exact_values_unchanged(self):
        spans = [Span(540, 1035)]
        self.assertEqual(round_spans(spans, 15), spans)

    def test_step_of_one_changes_nothing(self):
        spans = [Span(541, 1021)]
        self.assertEqual(round_spans(spans, 1), spans)

    def test_end_of_day_stays_valid(self):
        self.assertEqual(
            round_spans([Span(1400, 1440)], 30),
            [Span(1410, 1440)],
        )

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_spans([Span(60, 120)], step)

    def test_span_that_collapses_raises(self):
        with self.assertRaises(ValueError):
            round_spans([Span(61, 64)], 15)

class LabelTests(unittest.TestCase):
    def test_label_format(self):
        self.assertEqual(
            rounded_labels([Span(541, 1013)], 15),
            ["09:00-17:00 (8h 0m)"],
        )

    def test_label_with_minutes(self):
        self.assertEqual(
            rounded_labels([Span(540, 1035)], 15),
            ["09:00-17:15 (8h 15m)"],
        )

    def test_one_label_per_span(self):
        labels = rounded_labels(
            [Span(480, 600), Span(660, 720)], 30
        )
        self.assertEqual(len(labels), 2)

    def test_empty_list(self):
        self.assertEqual(rounded_labels([], 15), [])
